def lang_of(uid):
    return user_lang.get(uid, "ru")

def main_menu(lang):
    t = TEXT[lang]
    m = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=2)
    if lang == "ru":
        m.add(
            types.KeyboardButton(t["about_btn"]), types.KeyboardButton("📅 Расписание"),
            types.KeyboardButton("📚 Специальности"), types.KeyboardButton("🎓 Поступление"),
            types.KeyboardButton("💰 Гранты / Оплата"), types.KeyboardButton("📞 Контакты"),
            types.KeyboardButton("📰 Новости"), types.KeyboardButton("🌐 Сайт колледжа"),
            types.KeyboardButton(t["social_btn"]), types.KeyboardButton(t["ask_btn"]),
            types.KeyboardButton(t["lang_btn"]),
        )
    else:
        m.add(
            types.KeyboardButton(t["about_btn"]), types.KeyboardButton("📅 Сабақ кестесі"),
            types.KeyboardButton("📚 Мамандықтар"), types.KeyboardButton("🎓 Оқуға түсу"),
            types.KeyboardButton("💰 Грант / Төлем"), types.KeyboardButton("📞 Байланыс"),
            types.KeyboardButton("📰 Жаңалықтар"), types.KeyboardButton("🌐 Колледж сайты"),
            types.KeyboardButton(t["social_btn"]), types.KeyboardButton(t["ask_btn"]),
            types.KeyboardButton(t["lang_btn"]),
        )
    return m

def site_btn(lang):
    m = types.InlineKeyboardMarkup()
    txt = "🌐 Открыть сайт" if lang == "ru" else "🌐 Сайтты ашу"
    m.add(types.InlineKeyboardButton(txt, url=SITE))
    return m

def social_btn(lang):
    m = types.InlineKeyboardMarkup()
    m.add(types.InlineKeyboardButton("📸 Instagram", url="https://instagram.com/gumanitaricollegeinkrg"))
    m.add(types.InlineKeyboardButton("🎵 TikTok", url="https://tiktok.com/@gumlife_krg"))
    m.add(types.InlineKeyboardButton("📘 Facebook", url=FB))
    m.add(types.InlineKeyboardButton("🌐 Сайт", url=SITE))
    return m

def lang_keyboard():
    m = types.ReplyKeyboardMarkup(resize_keyboard=True)
    m.add(types.KeyboardButton("🇷🇺 Русский"), types.KeyboardButton("🇰🇿 Қазақша"))
    return m

@bot.message_handler(commands=['start'])
def start(message):
    bot.send_message(message.chat.id, "Выбери язык / Тілді таңда 👇", reply_markup=lang_keyboard())

@bot.message_handler(func=lambda m: m.text in ["🇷🇺 Русский", "🇰🇿 Қазақша", "🌐 Язык / Тіл", "🌐 Тіл / Язык"])
def set_lang(message):
    if message.text == "🇷🇺 Русский":
        user_lang[message.chat.id] = "ru"
    elif message.text == "🇰🇿 Қазақша":
        user_lang[message.chat.id] = "kz"
    else:
        bot.send_message(message.chat.id, "Выбери язык / Тілді таңда 👇", reply_markup=lang_keyboard())
        return
    lang = lang_of(message.chat.id)
    bot.send_message(message.chat.id, TEXT[lang]["welcome"], reply_markup=main_menu(lang))

